  function positionRow(c,z,row,index){var scoped=categoryMatches(c.id).filter(function(m){return m.stage===STAGES.GENERAL&&m.zoneId===z.id&&(m.winnerId===row.team.id||m.loserId===row.team.id);}),wins=scoped.filter(function(m){return m.winnerId===row.team.id;}).length,losses=scoped.length-wins,setsFor=0,setsAgainst=0;scoped.forEach(function(m){var isWinner=m.winnerId===row.team.id;matchSetsFor(m).forEach(function(s){setsFor+=isWinner?s.a:s.b;setsAgainst+=isWinner?s.b:s.a;});});var setWins=scoped.reduce(function(total,m){var isWinner=m.winnerId===row.team.id;return total+(isWinner?2:(m.score==='2-1'?1:0));},0),setLosses=scoped.reduce(function(total,m){var isWinner=m.winnerId===row.team.id;return total+(isWinner?(m.score==='2-1'?1:0):2);},0),ratio=function(a,b){return b?((a/b).toFixed(2)):a?'∞':'—';};return'<tr><td><span class="pos '+(index<2?'top':'')+'">'+(index+1)+'</span></td><td><strong>'+esc(row.team.name)+'</strong></td><td><b>'+row.classificationPoints+'</b></td><td>'+row.resultCount+'</td><td>'+wins+'</td><td>'+losses+'</td><td>'+setWins+'</td><td>'+setLosses+'</td><td>'+setsFor+'</td><td>'+setsAgainst+'</td><td><span class="result-chip">'+wins+'G / '+losses+'P</span></td><td>'+ratio(setWins,setLosses)+'</td><td>'+ratio(setsFor,setsAgainst)+'</td><td>0</td></tr>';}
  function positionsPage(){var c=category(),f=zoneFlow(c),zones=f.zones.filter(function(z){return z.id!==f.secondStageZoneId;}),has=zones.some(function(z){return z.teamIds.length;});return'<div class="toolbar"><div><p class="eyebrow">CLASIFICACIÓN AUTOMÁTICA</p><h2>Posiciones por zona</h2><p class="desc">Orden: PUNTOS, cociente de SET, cociente de PTOS y nombre como último criterio visual.</p></div><button class="secondary" data-view="matches">Ver partidos →</button></div>'+(has?'<div class="positions-stack">'+zones.map(function(z){var rows=zoneRows(c,z,STAGES.GENERAL);return'<section class="card position-card"><div class="card-title"><div><p class="eyebrow">TABLA DE POSICIONES</p><h2>'+esc(z.name)+'</h2></div><span class="zone-count">'+z.teamIds.length+' equipos</span></div><div class="table-wrap"><table class="table positions-table"><thead><tr><th>#</th><th>EQUIPO</th><th>PUNTOS</th><th>J</th><th>G</th><th>P</th><th>SF</th><th>SE</th><th>PG</th><th>PP</th><th>RESULTADOS</th><th>SET</th><th>PTOS</th><th>P.</th></tr></thead><tbody>'+rows.map(function(row,i){return positionRow(c,z,row,i);}).join('')+'</tbody></table></div></section>';}).join('')+'</div>':'<section class="card empty"><h2>Clasificación pendiente</h2><p>Creá zonas y asigná equipos para ver las posiciones.</p></section>');}
  function advance(target,limit){var c=category();if(!c)throw Error('Seleccioná una categoría.');var list=active(c.id);if(list.length<2)throw Error('Se necesitan al menos 2 equipos activos.');var ranking=standings(c.id,c.currentStage).filter(function(row){return list.some(function(t){return t.id===row.team.id;});}),keep=ranking.slice(0,Math.min(limit,list.length)).map(function(row){return row.team.id;});list.forEach(function(t){if(keep.indexOf(t.id)>=0){t.status=STATUS.QUALIFIED;t.stage=target;}else t.status=STATUS.ELIMINATED;});c.currentStage=target;saveState();}
  function generateTop16(){var c=category();if(!c||c.currentStage!==STAGES.GENERAL)throw Error('La etapa actual no es clasificación general.');advance(STAGES.TOP_16,16);}
  function generateTop8(){var c=category();if(!c||c.currentStage!==STAGES.TOP_16)throw Error('La etapa actual no es Top 16.');advance(STAGES.TOP_8,8);}
  function generateTop4(){var c=category();if(!c||c.currentStage!==STAGES.TOP_8)throw Error('La etapa actual no es Top 8.');advance(STAGES.TOP_4,4);}
  function advanceToSemifinals(){var c=category();if(!c||c.currentStage!==STAGES.TOP_4)throw Error('La etapa actual no es Top 4.');advance(STAGES.SEMIFINAL,4);}
  function advanceToFinal(){var c=category();if(!c||c.currentStage!==STAGES.SEMIFINAL)throw Error('La etapa actual no es semifinales.');advance(STAGES.FINAL,2);}
  function finishTournament(){var c=category();if(!c||c.currentStage!==STAGES.FINAL)throw Error('La categoría no está en la final.');var rows=standings(c.id,STAGES.FINAL).filter(function(r){return r.team.status===STATUS.ACTIVE||r.team.status===STATUS.QUALIFIED;});if(rows.length<2||!rows[0].stagePoints||!rows[1].stagePoints)throw Error('Cargá un puntaje para cada finalista.');c.championId=rows[0].team.id;c.runnerUpId=rows[1].team.id;c.currentStage=STAGES.FINISHED;rows[0].team.status=STATUS.CHAMPION;rows[1].team.status=STATUS.RUNNER_UP;saveState();}

  function badge(status){return'<span class="status '+status+'">'+STATUS_LABELS[status]+'</span>';}
  function stats(){var c=category(),entries=c?categoryEntries(c.id):[],allEntries=state.teams.reduce(function(all,t){return all.concat(t.scoreEntries);},[]);return'<div class="summary"><div class="stat"><i>▦</i><div><small>CATEGORÍAS</small><b>'+state.categories.length+'</b></div></div><div class="stat"><i>♙</i><div><small>EQUIPOS</small><b>'+state.teams.length+'</b></div></div><div class="stat"><i>●</i><div><small>CARGAS</small><b>'+allEntries.length+'</b></div></div><div class="stat"><i>★</i><div><small>PUNTOS '+(c?'ACTIVOS':'')+'</small><b>'+sum(entries.map(function(item){return item.entry.points;}))+'</b></div></div><div class="stat"><i>◈</i><div><small>ETAPA ACTUAL</small><b>'+(c?LABELS[c.currentStage]:'Clasificación')+'</b></div></div></div>';}
  function sidebar(){var c=category();return'<aside class="sidebar"><div class="brand"><span class="logo">P</span><div><b>Puntaje</b><small>NEWCOM</small></div></div><nav class="nav"><div class="nav-label">NAVEGACIÓN</div><button data-view="home" class="'+(view==='home'?'active':'')+'"><span>⌂</span> Inicio</button><button data-view="categories" class="'+(view==='categories'?'active':'')+'"><span>▦</span> Categorías <em>'+state.categories.length+'</em></button>'+(c?'<div class="nav-label" style="margin-top:22px">TORNEO +50</div><button data-view="zones" class="'+(view==='zones'?'active':'')+'"><span>◉</span> Zonas</button><button data-view="matches" class="'+(view==='matches'?'active':'')+'"><span>▥</span> Partidos</button><button data-view="positions" class="'+(view==='positions'?'active':'')+'"><span>▤</span> Posiciones</button><button data-view="teams" class="'+(view==='teams'?'active':'')+'"><span>♙</span> Equipos</button><button data-view="results" class="'+(view==='results'?'active':'')+'"><span>＋</span> Cargar resultado</button><button data-view="stage" class="'+(view==='stage'?'active':'')+'"><span>◈</span> Etapa actual</button>':'')+'</nav><div class="sidebar-foot"><div class="tip">● &nbsp;<strong>Resultados y posiciones por zona.</strong></div><small>v1.1 · Puntaje Newcom</small></div></aside>';}
  function shell(content){var c=category();return'<div class="app">'+sidebar()+'<div class="main"><header class="topbar"><div class="mobile-brand"><span class="logo">P</span><b>Puntaje Newcom</b></div><div class="crumb"><small>PUNTAJE NEWCOM</small><b>'+(c?esc(c.name):'Resumen general')+'</b></div><button class="theme" data-action="theme">'+(theme==='dark'?'☀ Modo claro':'☾ Modo oscuro')+'</button></header><main>'+content+'</main></div></div>';}
