  function home(){return'<div class="heading"><div><p class="eyebrow">PANEL PRINCIPAL</p><h1>Puntaje Newcom</h1><p class="desc">Acumulación de puntajes y clasificación por categoría.</p></div><div class="heading-actions"><button class="secondary" data-action="load-demo">Ver demo +50</button><button class="primary" data-action="new-category">＋ Crear categoría</button></div></div>'+stats()+'<div id="notice"></div>'+(state.categories.length?'<section class="card"><div class="card-title"><div><p class="eyebrow">CATEGORÍAS</p><h2>Tus categorías</h2></div><button class="link" data-view="categories">Ver todas →</button></div>'+state.categories.map(function(c){return'<button class="category-row" data-category="'+c.id+'"><span class="avatar">'+initial(c.name)+'</span><span class="category-name"><b>'+esc(c.name)+'</b><small>'+teams(c.id).length+' equipos · '+categoryMatches(c.id).length+' partidos</small></span><span class="badge">'+LABELS[c.currentStage]+'</span><span>→</span></button>';}).join('')+'</section>':'<section class="card empty"><div class="big">◎</div><h2>No hay categorías creadas.</h2><p>Creá una categoría para comenzar a cargar puntajes.</p><button class="primary" data-action="new-category">＋ Crear categoría</button></section>');}
